 if(phase==2&&Time.time-start>1.1f){Check(caster.mana>=mp+1&&caster.mana<mp+1.4f,"Combat generates1Faith per second");float h=ally.health;a.melee=false;ally.GetDamage(100,pure,foeOwner,a,true,out _);Check(Mathf.Abs(h-ally.health-85)<.1f,"Faith shield reduces ranged damage15percent");h=ally.health;a.melee=true;ally.GetDamage(100,pure,foeOwner,a,true,out _);Check(Mathf.Abs(h-ally.health-100)<.1f,"Faith shield excludes melee");h=ally.health;a.melee=false;ally.GetDamage(100,pure,foeOwner,a,false,out _);Check(Mathf.Abs(h-ally.health-100)<.1f,"Faith shield excludes indirect damage");Check(!far.effectors.Any(e=>e.effector==aura.effectors[0]),"Shield excludes outside radius");Capture("inquisitor-dome-final.png");caster.SetHP(500);ally.SetHP(500);Check(Cast(prayer),"Prayer button accepted");start=Time.time;phase=3;return;}
