 if(phase==8&&Time.time-start>22){Check(!caster.polymorphed&&!caster.melee,"After20sec original ranged form restored");Check(Mathf.Abs(caster.attackRange-range)<.01f&&caster.projectileGO,"Original range and projectile restored");Check(!Cast(dash),"Avatar skill closes after return");Reset(bolt);a.transform.position=caster.transform.position+Vector3.forward*3;Check(Cast(bolt),"Bolt reusable after return");start=Time.time;phase=9;return;}
