 static bool Cast(CompositeSkill s){Register();return caster&&caster.UseAbilityItem(Array.IndexOf(caster.abilities,s),false,null,Vector3.zero,true);}
 static void Register(){var mm=MatchManager.instance;var flags=System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic;((TeamWaveConfig)typeof(MatchManager).GetField("teamA",flags).GetValue(mm)).ownerPlayer=0;((TeamWaveConfig)typeof(MatchManager).GetField("teamB",flags).GetValue(mm)).ownerPlayer=foeOwner;var lists=(List<Unit>[])typeof(MatchManager).GetField("teamUnits",flags).GetValue(mm);lists[0].Clear();lists[0].AddRange(new[]{caster,ally,far,second}.Where(u=>u&&!u.dead));lists[1].Clear();lists[1].AddRange(new[]{a,b}.Where(u=>u&&!u.dead));}
 static void Reset(CompositeSkill s)=>caster.ChangeAbilityCooldown(-100,Array.IndexOf(caster.abilities,s),false);
 static void Check(bool ok,string text){results.Add((ok?"PASS ":"FAIL ")+text);if(!ok)errors.Add(text);File.WriteAllLines(W+"inquisitor-runtime-results.txt",results);}
 static Unit Spawn(Vector3 p,int owner,bool hero=false){var asset=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Resources/UnitPrefabs/Units/"+(hero?"Heroes/Humans/Inquisitor_Base":"Humans/Swordsman")+".prefab").GetComponent<Unit>();var u=Unit.SpawnInternal(asset,p,0,owner);u.maxHealth=10000;u.SetHP(10000);u.armor=0;u.healthRegen=0;u.canAttack=false;u.doNotLookForTargets=true;u.Hold();u.FoWVisible=true;u.ShowRenderers();var au=u.GetComponent<AutoAbilityUser>();if(au)au.enabled=false;return u;}
