 if(!NavMesh.SamplePosition(new Vector3(113,0,33),out var pos,10,NavMesh.AllAreas))throw new Exception("No navmesh");center=pos.position;foeOwner=Enumerable.Range(1,SlotManager.instance.playerTeam.Length-2).First(i=>SlotManager.instance.playerTeam[i]!=SlotManager.instance.playerTeam[0]);caster=Spawn(center,0,true);a=Spawn(center+Vector3.forward*3,foeOwner);b=Spawn(center+Vector3.forward*5,foeOwner);ally=Spawn(center+Vector3.left*1.5f,0);far=Spawn(center+Vector3.right*15,0);range=caster.attackRange;
 bolt=caster.abilities.OfType<CompositeSkill>().Single(x=>x.name=="Inquisitor_CleansingBolt");prayer=caster.abilities.OfType<CompositeSkill>().Single(x=>x.name=="Inquisitor_Prayer");ascension=caster.abilities.OfType<CompositeSkill>().Single(x=>x.name=="Inquisitor_Ascension");dash=caster.abilities.OfType<CompositeSkill>().Single(x=>x.name=="Avatar_RighteousDash");blade=caster.abilities.OfType<CompositeSkill>().Single(x=>x.name=="Avatar_EcstasyBlade");aura=caster.abilities.OfType<EffectorAura>().Single();pure=AssetDatabase.LoadAssetAtPath<DamageType>("Assets/Resources/DamageTypes/Pure.asset");caster.LookAtInstant(new Vector2(a.transform.position.x,a.transform.position.z));
 foreach(var m in UnityEngine.Object.FindObjectsByType<MonoBehaviour>(FindObjectsSortMode.None))if(m.GetType().Name=="Camera_TopDown"||m.GetType().Name=="CameraAxisLock")m.enabled=false;camera=Camera.main;camera.transform.SetParent(null,true);camera.transform.position=center+new Vector3(7,8,-7);camera.transform.LookAt(center+Vector3.forward);camera.orthographic=true;camera.orthographicSize=4.5f;}
 static void Begin(){if(UnityEngine.SceneManagement.SceneManager.GetActiveScene().path!="Assets/Scenes/Artsiom.unity"&&UnityEngine.SceneManagement.SceneManager.GetActiveScene().path!=Scene)throw new Exception("Open basic Artsiom before this check");if(!AssetDatabase.LoadAssetAtPath<SceneAsset>(Scene)){if(!AssetDatabase.CopyAsset("Assets/Scenes/Artsiom.unity",Scene))throw new Exception("Cannot copy Artsiom");}EditorSceneManager.OpenScene(Scene);foreach(var m in UnityEngine.Object.FindObjectsByType<MonoBehaviour>(FindObjectsSortMode.None))if(m.GetType().Name=="MatchManager")m.enabled=false;foreach(var f in UnityEngine.Object.FindObjectsByType<FogOfWar>(FindObjectsSortMode.None))f.TurnOff=true;
